const DB_NAME='qingyue-web-v1';
const opened=new Promise((resolve,reject)=>{const request=indexedDB.open(DB_NAME,1);request.onupgradeneeded=()=>{request.result.createObjectStore('folders',{keyPath:'id'});request.result.createObjectStore('documents',{keyPath:'id'});};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);request.onblocked=()=>reject(new Error('请关闭其他晴阅网页后重试'));});
export const uuid=()=>crypto.randomUUID?.()||`${Date.now().toString(16)}-${crypto.getRandomValues(new Uint32Array(4)).join('-')}`;
export const copy=value=>structuredClone(value);
export async function sha256(blob){const bytes=blob instanceof Blob?await blob.arrayBuffer():blob;return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');}
async function read(store,key){const db=await opened;return new Promise((resolve,reject)=>{const request=db.transaction(store).objectStore(store)[key===undefined?'getAll':'get'](key);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
export const listDocuments=()=>read('documents');export const listFolders=()=>read('folders');export const getDocument=id=>read('documents',id);
// Both object stores must belong to the same readonly transaction for a backup snapshot.
export async function readCollection(){const db=await opened;return new Promise((resolve,reject)=>{const tx=db.transaction(['folders','documents'],'readonly'),folders=tx.objectStore('folders').getAll(),documents=tx.objectStore('documents').getAll();tx.oncomplete=()=>resolve({folders:folders.result,documents:documents.result});tx.onerror=tx.onabort=()=>reject(tx.error||new Error('无法读取完整备份快照'));});}
async function transaction(stores,callback){const db=await opened;return new Promise((resolve,reject)=>{const tx=db.transaction(stores,'readwrite');let result,failure;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(failure||tx.error||new Error('本机存储失败，请先导出备份'));tx.onabort=()=>reject(failure||tx.error||new Error('保存失败，可能空间不足'));try{callback(tx,v=>{result=v;},error=>{failure=error;tx.abort();});}catch(error){failure=error;tx.abort();}});}
export async function insertDocument(document){return transaction(['documents','folders'],(tx,done,fail)=>{const write=()=>{tx.objectStore('documents').add(document);done(document);};if(!document.folderId)write();else{const request=tx.objectStore('folders').get(document.folderId);request.onsuccess=()=>request.result?write():fail(new Error('文件夹已被移除，请重新导入'));}});}
export async function updateDocument(id,expectedRevision,update){return transaction(['documents','folders'],(tx,done,fail)=>{const request=tx.objectStore('documents').get(id);request.onsuccess=()=>{try{const old=request.result;if(!old)throw new Error('资料已被删除');if(expectedRevision!==undefined&&old.revision!==expectedRevision)throw new Error('资料已在其他窗口更新，请返回后重新打开');const next=update(copy(old));next.revision=old.revision+1;next.modified=Date.now();const write=()=>{tx.objectStore('documents').put(next);done(next);};if(next.folderId){const target=tx.objectStore('folders').get(next.folderId);target.onsuccess=()=>target.result?write():fail(new Error('目标文件夹已不存在'));}else write();}catch(error){fail(error);}};});}
export async function removeDocument(id){return transaction(['documents'],(tx,done)=>{tx.objectStore('documents').delete(id);done();});}
export function validFolderTree(folders){const ids=new Map();for(const folder of folders){if(!folder||typeof folder.id!=='string'||!folder.id||ids.has(folder.id)||typeof folder.parentId!=='string'||typeof folder.name!=='string'||!folder.name.trim()||folder.name.length>100)throw new Error('文件夹数据无效');ids.set(folder.id,folder);}const sibling=new Set();for(const folder of folders){const key=folder.parentId+'\0'+folder.name.toLocaleLowerCase();if(sibling.has(key))throw new Error('同级已有同名文件夹');sibling.add(key);let current=folder,seen=new Set();while(current.parentId){if(seen.has(current.id)||seen.size>=32)throw new Error('文件夹不能循环或超过 32 层');seen.add(current.id);current=ids.get(current.parentId);if(!current)throw new Error('父文件夹不存在');}}return true;}
export async function saveFolder(folder){return transaction(['folders'],(tx,done,fail)=>{const store=tx.objectStore('folders'),request=store.getAll();request.onsuccess=()=>{try{const folders=request.result.filter(x=>x.id!==folder.id);folders.push(folder);validFolderTree(folders);store.put(folder);done(folder);}catch(error){fail(error);}};});}
export async function deleteFolder(id){return transaction(['folders','documents'],(tx,done,fail)=>{const f=tx.objectStore('folders').getAll(),d=tx.objectStore('documents').getAll();let folders,docs;const check=()=>{if(!folders||!docs)return;if(folders.some(x=>x.parentId===id)||docs.some(x=>x.folderId===id))return fail(new Error('请先移走子文件夹和资料（包括最近删除中的资料）'));tx.objectStore('folders').delete(id);done();};f.onsuccess=()=>{folders=f.result;check();};d.onsuccess=()=>{docs=d.result;check();};});}
export async function restoreCollection(folders,documents){validFolderTree(folders);return transaction(['folders','documents'],(tx,done)=>{for(const folder of folders)tx.objectStore('folders').add(folder);for(const doc of documents)tx.objectStore('documents').add(doc);done();});}
export function blankDocument(name,blob,folderId,pages,hash){return{id:uuid(),name,blob,folderId,pages,hash,page:1,revision:1,created:Date.now(),modified:Date.now(),trashed:false,annotations:{},bookmarks:[]};}
